#!/usr/bin/env python3
"""Stdlib-only xlsx dumper: all sheets -> structured TSV dump with row numbers.

Handles: sharedStrings, inlineStr, booleans, merged ranges, cell comments.
"""
import sys, zipfile, re
import xml.etree.ElementTree as ET

NS_MAIN = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
NS_REL  = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'


def col_to_num(col):
    n = 0
    for ch in col:
        n = n * 26 + (ord(ch) - 64)
    return n


def split_ref(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    return m.group(1), int(m.group(2))


def main(path):
    z = zipfile.ZipFile(path)
    names = z.namelist()

    sst = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall(f'{NS_MAIN}si'):
            sst.append(''.join(t.text or '' for t in si.iter(f'{NS_MAIN}t')))

    wb = ET.fromstring(z.read('xl/workbook.xml'))
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    relmap = {r.get('Id'): r.get('Target') for r in rels}

    sheets = []
    for sh in wb.iter(f'{NS_MAIN}sheet'):
        rid = sh.get(f'{NS_REL}id')
        target = relmap.get(rid, '')
        if target and not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        sheets.append((sh.get('name'), target))

    out = []
    out.append(f'FILE: {path}')
    out.append(f'SHEETS ({len(sheets)}): ' + ' | '.join(n for n, _ in sheets))

    for name, target in sheets:
        if not target or target not in names:
            out.append(f'!! sheet {name}: target {target} not found in zip')
            continue
        out.append('=' * 110)
        out.append(f'### SHEET: {name}  [{target}]')
        root = ET.fromstring(z.read(target))
        dim = root.find(f'{NS_MAIN}dimension')
        if dim is not None:
            out.append(f'DIMENSION: {dim.get("ref")}')

        merges = []
        merge_el = root.find(f'{NS_MAIN}mergeCells')
        if merge_el is not None:
            merges = [m.get('ref') for m in merge_el]
        if merges:
            out.append('MERGED: ' + ', '.join(merges))

        cells = {}
        maxrow = maxcol = 0
        sd = root.find(f'{NS_MAIN}sheetData')
        if sd is not None:
            for row in sd.findall(f'{NS_MAIN}row'):
                for c in row.findall(f'{NS_MAIN}c'):
                    ref = c.get('r') or ''
                    t = c.get('t')
                    v = c.find(f'{NS_MAIN}v')
                    is_ = c.find(f'{NS_MAIN}is')
                    val = None
                    if t == 's' and v is not None:
                        val = sst[int(v.text)]
                    elif t == 'inlineStr' and is_ is not None:
                        val = ''.join(x.text or '' for x in is_.iter(f'{NS_MAIN}t'))
                    elif v is not None and v.text is not None:
                        val = v.text
                    if val is None or val == '':
                        continue
                    col, rn = split_ref(ref)
                    ci = col_to_num(col)
                    cells[(rn, ci)] = val
                    maxrow = max(maxrow, rn)
                    maxcol = max(maxcol, ci)

        out.append(f'GRID: {maxrow} rows x {maxcol} cols; non-empty cells: '
                   f'{len(cells)}; merged ranges: {len(merges)}')
        for rn in range(1, maxrow + 1):
            rowvals = []
            empty = True
            for cc in range(1, maxcol + 1):
                v = cells.get((rn, cc))
                if v is None:
                    rowvals.append('')
                else:
                    empty = False
                    rowvals.append(v.replace('\t', ' ').replace('\r', '').replace('\n', '\\n'))
            if not empty:
                out.append(f'R{rn}\t' + '\t'.join(rowvals))

    # comments (notes) if any
    for cn in sorted(n for n in names if re.match(r'xl/comments\d+\.xml$', n)):
        out.append('=' * 110)
        out.append(f'### COMMENTS FILE: {cn}')
        root = ET.fromstring(z.read(cn))
        for c in root.iter(f'{NS_MAIN}comment'):
            ref = c.get('ref')
            text = ''.join(t.text or '' for t in c.iter(f'{NS_MAIN}t'))
            out.append(f'NOTE[{ref}]: {text}')

    print('\n'.join(out))


if __name__ == '__main__':
    main(sys.argv[1])

